local Luna = loadstring(game:HttpGet("https://raw.githubusercontent.com/Nebula-Softworks/Luna-Interface-Suite/refs/heads/master/source.lua", true))()

local Window = Luna:CreateWindow({
	Name = "Ahmetcik SCR",
	Subtitle = "IDK Studios",
	LogoID = "82795327169782",
	LoadingEnabled = true,
	LoadingTitle = "Luna InterLoading",
	LoadingSubtitle = "by AhmetcikScripts",
	ConfigSettings = {
		RootFolder = nil,
		ConfigFolder = "Big Hub"
	},
	KeySystem = false
})

Window:CreateHomeTab({
	SupportedExecutors = {"Synapse X","Fluxus","Delta"},
	DiscordInvite = "QvxwUGNs",
	Icon = 1
})

local Tab = Window:CreateTab({
	Name = "Main",
	Icon = "view_in_ar",
	ShowTitle = true
})

Luna:Notification({
	Title = "Ahmetcik Hub Notification",
	Content = "Please leave a comment for this script!"
})

-- KillBrick kald�rma
local Button = Tab:CreateButton({
	Name = "Remove KillBrick",
	Description = "Prevents you from dying for falling down.",
	Callback = function()
		local killBrick = game.Workspace:FindFirstChild("Map") and game.Workspace.Map:FindFirstChild("Classic") and game.Workspace.Map.Classic:FindFirstChild("KillBrick")
		if killBrick then
			killBrick:Destroy()
			Luna:Notification({Title = "KillBrick Removed", Content = "KillBrick removed!"})
		else
			Luna:Notification({Title = "Error", Content = "KillBrick not found or already deleted!"})
		end
	end
})

local Button = Tab:CreateButton({
	Name = "Teleport to Destroyer Spawn",
	Description = "Teleports the player to Destroyer Spawn.",
	Callback = function()
		local player = game.Players.LocalPlayer
		if player and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
			player.Character:MoveTo(game.Workspace.Map.Classic.Shooter.PARTSPAWNAREA.Position)
		end
	end
})

Tab:CreateSection("Main Setting")
Tab:CreateDivider()

local WalkSpeedSlider = Tab:CreateSlider({
	Name = "WalkSpeed",
	Range = {0, 100},
	Increment = 1,
	CurrentValue = 16,
	Callback = function(Value)
		local player = game.Players.LocalPlayer
		if player and player.Character and player.Character:FindFirstChildOfClass("Humanoid") then
			player.Character:FindFirstChildOfClass("Humanoid").WalkSpeed = Value
		end
	end
}, "WalkSpeed")

local Button = Tab:CreateButton({
	Name = "Invisibility Gui",
	Description = "Opens a gui for become invisible.",
	Callback = function()
    loadstring(game:HttpGet('https://pastebin.com/raw/3Rnd9rHf'))()
    
		end
})

Luna:Display()
